shapes=[]
for r in range(4):
 for c in range(6):
  block={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if block<=cells: shapes.append((block,1))
  for miss in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   s=block-{miss}
   if s<=cells: shapes.append((s,{(r,c):2,(r,c+1):4,(r+1,c):3,(r+1,c+1):5}[miss]))
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem)
 for s,col in shapes:
  if x in s and s<=rem: rec(rem-s,chosen+[(s,col)])
rec(cells,[])
len(sol), sol[:1]
